INSERT INTO public.kb_articles (
  slug, category_id, title_ar, title_en, excerpt_ar, excerpt_en, content_ar,
  meta_title, meta_description, keywords, reading_minutes, faq, "references",
  external_sources, author_name, is_featured, status, generation_source, published_at
) VALUES
(
  'ifrs-9-expected-credit-loss-guide',
  (SELECT id FROM public.kb_categories WHERE slug = 'international-accounting-standards'),
  'دليل تطبيق نموذج الخسائر الائتمانية المتوقعة (ECL) وفق معيار IFRS 9',
  'IFRS 9 Expected Credit Loss (ECL) Model: A Practical Guide',
  'دليل تطبيقي حول نموذج الخسائر الائتمانية المتوقعة وفق IFRS 9 يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to the IFRS 9 expected credit loss (ECL) model, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع نموذج الخسائر الائتمانية المتوقعة وفق IFRS 9 يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "يصنف النموذج الأداة المالية ضمن ثلاث مراحل حسب تدهور جودتها الائتمانية منذ الاعتراف الأولي، وينعكس ذلك مباشرة على قيمة المخصص الواجب رصده."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: تصنيف الأدوات المالية إلى المراحل الثلاث، احتساب احتمال التعثر PD والخسارة عند التعثر LGD، وبناء مصفوفة المخصصات المبسطة لذمم العملاء.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في نموذج الخسائر الائتمانية المتوقعة وفق IFRS 9."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'نموذج الخسائر الائتمانية المتوقعة وفق IFRS 9 | دليل عملي للمحاسبين',
  'دليل تطبيقي حول نموذج الخسائر الائتمانية المتوقعة وفق IFRS 9 يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['نموذج الخسائر الائتمانية المتوقعة وفق IFRS 9', 'تصنيف الأدوات المالية إلى المراحل الثلاث', 'احتساب احتمال التعثر PD والخسارة عند التعثر LGD', 'بناء مصفوفة المخصصات المبسطة لذمم العملاء'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق نموذج الخسائر الائتمانية المتوقعة وفق IFRS 9؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://www.ifrs.org/issued-standards/list-of-standards/ifrs-9-financial-instruments/"}]$refs$::jsonb,
  $sources$[{"name": "المصدر المرجعي", "url": "https://www.ifrs.org/issued-standards/list-of-standards/ifrs-9-financial-instruments/"}]$sources$::jsonb,
  'أحمد المدني',
  false,
  'published',
  'editorial',
  '2026-09-07 08:00:00+03'::timestamptz
),
(
  'ifrs-10-consolidated-financial-statements-guide',
  (SELECT id FROM public.kb_categories WHERE slug = 'international-accounting-standards'),
  'دليل تقييم السيطرة وإعداد القوائم المالية الموحدة وفق معيار IFRS 10',
  'IFRS 10: Assessing Control and Preparing Consolidated Financial Statements',
  'دليل تطبيقي حول إعداد القوائم المالية الموحدة وتقييم السيطرة وفق IFRS 10 يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to IFRS 10 consolidated financial statements and control assessment, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع إعداد القوائم المالية الموحدة وتقييم السيطرة وفق IFRS 10 يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "تقوم السيطرة وفق IFRS 10 على ثلاثة عناصر مجتمعة: السلطة على المنشأة المستثمر فيها، والتعرض لعوائد متغيرة، والقدرة على التأثير في تلك العوائد عبر تلك السلطة."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: اختبار عناصر السيطرة الثلاثة: السلطة والعائد المتغير والربط بينهما، معالجة حقوق التصويت المحتملة والترتيبات الهيكلية، وتنفيذ إجراءات التوحيد وحذف المعاملات البينية.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في إعداد القوائم المالية الموحدة وتقييم السيطرة وفق IFRS 10."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'إعداد القوائم المالية الموحدة وتقييم السيطرة وفق IFRS 10 | دليل عملي للمحاسبين',
  'دليل تطبيقي حول إعداد القوائم المالية الموحدة وتقييم السيطرة وفق IFRS 10 يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['إعداد القوائم المالية الموحدة وتقييم السيطرة وفق IFRS 10', 'اختبار عناصر السيطرة الثلاثة: السلطة والعائد المتغير والربط بينهما', 'معالجة حقوق التصويت المحتملة والترتيبات الهيكلية', 'تنفيذ إجراءات التوحيد وحذف المعاملات البينية'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق إعداد القوائم المالية الموحدة وتقييم السيطرة وفق IFRS 10؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://www.ifrs.org/issued-standards/list-of-standards/ifrs-10-consolidated-financial-statements/"}]$refs$::jsonb,
  $sources$[{"name": "المصدر المرجعي", "url": "https://www.ifrs.org/issued-standards/list-of-standards/ifrs-10-consolidated-financial-statements/"}]$sources$::jsonb,
  'أحمد المدني',
  false,
  'published',
  'editorial',
  '2026-09-07 08:10:00+03'::timestamptz
),
(
  'ias-24-related-party-disclosures-guide',
  (SELECT id FROM public.kb_categories WHERE slug = 'international-accounting-standards'),
  'دليل إفصاحات الأطراف ذات العلاقة وفق معيار المحاسبة الدولي IAS 24',
  'IAS 24 Related Party Disclosures: A Practical Guide',
  'دليل تطبيقي حول إفصاحات الأطراف ذات العلاقة وفق معيار IAS 24 يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to IAS 24 related party disclosures, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع إفصاحات الأطراف ذات العلاقة وفق معيار IAS 24 يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "يوسّع المعيار تعريف الطرف ذي العلاقة ليشمل موظفي الإدارة الرئيسيين وأفراد أسرهم المقربين، وليس فقط الشركات التابعة والزميلة."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: حصر الأطراف ذات العلاقة وفق تعريف السيطرة والتأثير الجوهري، توثيق طبيعة العلاقة وشروط المعاملات مقارنة بشروط السوق، والإفصاح عن تعويضات الإدارة العليا والأرصدة القائمة.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في إفصاحات الأطراف ذات العلاقة وفق معيار IAS 24."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'إفصاحات الأطراف ذات العلاقة وفق معيار IAS 24 | دليل عملي للمحاسبين',
  'دليل تطبيقي حول إفصاحات الأطراف ذات العلاقة وفق معيار IAS 24 يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['إفصاحات الأطراف ذات العلاقة وفق معيار IAS 24', 'حصر الأطراف ذات العلاقة وفق تعريف السيطرة والتأثير الجوهري', 'توثيق طبيعة العلاقة وشروط المعاملات مقارنة بشروط السوق', 'الإفصاح عن تعويضات الإدارة العليا والأرصدة القائمة'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق إفصاحات الأطراف ذات العلاقة وفق معيار IAS 24؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://www.ifrs.org/issued-standards/list-of-standards/ias-24-related-party-disclosures/"}]$refs$::jsonb,
  $sources$[{"name": "المصدر المرجعي", "url": "https://www.ifrs.org/issued-standards/list-of-standards/ias-24-related-party-disclosures/"}]$sources$::jsonb,
  'أحمد المدني',
