(
  'ifrs-15-revenue-recognition-five-step-model',
  (SELECT id FROM public.kb_categories WHERE slug = 'international-accounting-standards'),
  'دليل تطبيق نموذج الخطوات الخمس للاعتراف بالإيراد وفق معيار IFRS 15',
  'IFRS 15: Applying the Five-Step Revenue Recognition Model',
  'دليل تطبيقي حول نموذج الخطوات الخمس للاعتراف بالإيراد وفق IFRS 15 يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to the IFRS 15 five-step revenue recognition model, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع نموذج الخطوات الخمس للاعتراف بالإيراد وفق IFRS 15 يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "يبدأ التطبيق بتحديد العقد مع العميل، ثم تحديد التزامات الأداء المنفصلة التي يجب معالجة كل منها بشكل مستقل عند الاعتراف بالإيراد."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: تحديد العقد والتزامات الأداء المنفصلة داخله، تحديد سعر المعاملة وتوزيعه على التزامات الأداء، والاعتراف بالإيراد عند أو خلال تحقق الأداء.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في نموذج الخطوات الخمس للاعتراف بالإيراد وفق IFRS 15."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'نموذج الخطوات الخمس للاعتراف بالإيراد وفق IFRS 15 | دليل عملي للمحاسبين',
  'دليل تطبيقي حول نموذج الخطوات الخمس للاعتراف بالإيراد وفق IFRS 15 يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
