(
  'zakat-mixed-ownership-companies-saudi',
  (SELECT id FROM public.kb_categories WHERE slug = 'zakat-tax-ksa'),
  'دليل احتساب الزكاة والضريبة للشركات ذات الملكية المختلطة في السعودية',
  'Zakat and Tax Calculation for Mixed-Ownership Companies in Saudi Arabia',
  'دليل تطبيقي حول احتساب الزكاة للشركات ذات الملكية المختلطة (سعودية وأجنبية) يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to zakat calculation for companies with mixed Saudi and foreign ownership, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع احتساب الزكاة للشركات ذات الملكية المختلطة (سعودية وأجنبية) يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "تخضع حصة الشركاء السعوديين وحصة دول مجلس التعاون للزكاة، بينما تخضع حصة الشركاء غير السعوديين لضريبة الدخل، ما يستلزم فصل الوعاءين بدقة."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: تحديد نسبة الملكية السعودية والأجنبية من السجل التجاري، احتساب وعاء الزكاة على الحصة السعودية ووعاء الضريبة على الحصة الأجنبية، وتوزيع المصروفات المشتركة بين الوعائين بأسلوب موثق.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في احتساب الزكاة للشركات ذات الملكية المختلطة (سعودية وأجنبية)."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'احتساب الزكاة للشركات ذات الملكية المختلطة (سعودية وأجنبية) | دليل عملي للمحاسبين',
  'دليل تطبيقي حول احتساب الزكاة للشركات ذات الملكية المختلطة (سعودية وأجنبية) يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['احتساب الزكاة للشركات ذات الملكية المختلطة (سعودية وأجنبية)', 'تحديد نسبة الملكية السعودية والأجنبية من السجل التجاري', 'احتساب وعاء الزكاة على الحصة السعودية ووعاء الضريبة على الحصة الأجنبية', 'توزيع المصروفات المشتركة بين الوعائين بأسلوب موثق'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق احتساب الزكاة للشركات ذات الملكية المختلطة (سعودية وأجنبية)؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
