(
  'withholding-tax-saudi-arabia-guide',
  (SELECT id FROM public.kb_categories WHERE slug = 'zakat-tax-ksa'),
  'دليل ضريبة الاستقطاع في السعودية: الفئات الخاضعة والنسب والإقرار',
  'Withholding Tax in Saudi Arabia: Categories, Rates, and Filing',
  'دليل تطبيقي حول ضريبة الاستقطاع (Withholding Tax) في السعودية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to withholding tax (WHT) in Saudi Arabia, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع ضريبة الاستقطاع (Withholding Tax) في السعودية يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "تُستقطع الضريبة عند الدفع لغير المقيم مقابل خدمات أو دخل مصدره السعودية، وتختلف النسبة باختلاف نوع الدفعة ووجود اتفاقية ازدواج ضريبي من عدمه."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: تحديد ما إذا كانت الجهة المستفيدة غير مقيمة وليس لها منشأة دائمة، تطبيق النسبة الصحيحة حسب نوع الدفعة (خدمات، إتاوات، توزيعات أرباح)، وسداد الضريبة المستقطعة والإقرار عنها خلال المهلة النظامية.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في ضريبة الاستقطاع (Withholding Tax) في السعودية."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'ضريبة الاستقطاع (Withholding Tax) في السعودية | دليل عملي للمحاسبين',
  'دليل تطبيقي حول ضريبة الاستقطاع (Withholding Tax) في السعودية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['ضريبة الاستقطاع (Withholding Tax) في السعودية', 'تحديد ما إذا كانت الجهة المستفيدة غير مقيمة وليس لها منشأة دائمة', 'تطبيق النسبة الصحيحة حسب نوع الدفعة (خدمات، إتاوات، توزيعات أرباح)', 'سداد الضريبة المستقطعة والإقرار عنها خلال المهلة النظامية'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق ضريبة الاستقطاع (Withholding Tax) في السعودية؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://zatca.gov.sa/ar/RulesRegulations/Taxes/Pages/IncomeTax.aspx"}]$refs$::jsonb,
  $sources$[{"name": "المصدر المرجعي", "url": "https://zatca.gov.sa/ar/RulesRegulations/Taxes/Pages/IncomeTax.aspx"}]$sources$::jsonb,
