(
  'zakat-tax-return-amendment-procedure',
  (SELECT id FROM public.kb_categories WHERE slug = 'zakat-tax-ksa'),
  'دليل تعديل الإقرار الزكوي أو الضريبي بعد تقديمه لدى هيئة الزكاة والضريبة والجمارك',
  'How to Amend a Zakat or Tax Return After Submission (ZATCA)',
  'دليل تطبيقي حول تعديل الإقرار الزكوي أو الضريبي بعد التقديم يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to amending a zakat or tax return after submission, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع تعديل الإقرار الزكوي أو الضريبي بعد التقديم يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "تتيح المنصة الإلكترونية تعديل الإقرار المقدَّم خلال فترة محددة، لكن التعديل بعد بدء الفحص أو انتهاء المهلة قد يستلزم إجراءً مختلفًا عبر طلب رسمي."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: تحديد سبب التعديل ونوعه (خطأ حسابي، بيانات ناقصة، تصحيح تصنيف)، تقديم طلب التعديل عبر البوابة الإلكترونية خلال المهلة النظامية، ومتابعة أثر التعديل على الفروق الزكوية أو الضريبية والغرامات المحتملة.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في تعديل الإقرار الزكوي أو الضريبي بعد التقديم."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'تعديل الإقرار الزكوي أو الضريبي بعد التقديم | دليل عملي للمحاسبين',
  'دليل تطبيقي حول تعديل الإقرار الزكوي أو الضريبي بعد التقديم يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['تعديل الإقرار الزكوي أو الضريبي بعد التقديم', 'تحديد سبب التعديل ونوعه (خطأ حسابي، بيانات ناقصة، تصحيح تصنيف)', 'تقديم طلب التعديل عبر البوابة الإلكترونية خلال المهلة النظامية', 'متابعة أثر التعديل على الفروق الزكوية أو الضريبية والغرامات المحتملة'],
  5,
