(
  'vat-ecommerce-digital-services-saudi',
  (SELECT id FROM public.kb_categories WHERE slug = 'vat'),
  'دليل ضريبة القيمة المضافة على التجارة الإلكترونية والخدمات الرقمية العابرة للحدود',
  'VAT on E-Commerce and Cross-Border Digital Services in Saudi Arabia',
  'دليل تطبيقي حول ضريبة القيمة المضافة على التجارة الإلكترونية والخدمات الرقمية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to VAT on e-commerce and digital services in Saudi Arabia, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع ضريبة القيمة المضافة على التجارة الإلكترونية والخدمات الرقمية يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "تُفرض الضريبة على الخدمات الرقمية بحسب مكان استفادة العميل المقيم في السعودية، وليس بالضرورة مكان تأسيس المزود أو خوادمه."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: تحديد مكان توريد الخدمة الرقمية وفق مكان إقامة العميل، تسجيل المزود غير المقيم أو تطبيق آلية الاحتساب العكسي، وإصدار فواتير إلكترونية متوافقة لعمليات البيع عبر المنصات.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في ضريبة القيمة المضافة على التجارة الإلكترونية والخدمات الرقمية."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'ضريبة القيمة المضافة على التجارة الإلكترونية والخدمات الرقمية | دليل عملي للمحاسبين',
  'دليل تطبيقي حول ضريبة القيمة المضافة على التجارة الإلكترونية والخدمات الرقمية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['ضريبة القيمة المضافة على التجارة الإلكترونية والخدمات الرقمية', 'تحديد مكان توريد الخدمة الرقمية وفق مكان إقامة العميل', 'تسجيل المزود غير المقيم أو تطبيق آلية الاحتساب العكسي', 'إصدار فواتير إلكترونية متوافقة لعمليات البيع عبر المنصات'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق ضريبة القيمة المضافة على التجارة الإلكترونية والخدمات الرقمية؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://zatca.gov.sa/ar/RulesRegulations/Taxes/Pages/VAT.aspx"}]$refs$::jsonb,
