(
  'vat-grouping-corporate-groups-guide',
  (SELECT id FROM public.kb_categories WHERE slug = 'vat'),
  'دليل التسجيل الضريبي الموحد VAT Grouping لمجموعات الشركات المرتبطة',
  'VAT Grouping for Corporate Groups: Benefits and Requirements',
  'دليل تطبيقي حول التسجيل الضريبي الموحد (VAT Grouping) للمجموعات المرتبطة يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to VAT grouping for related corporate groups, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع التسجيل الضريبي الموحد (VAT Grouping) للمجموعات المرتبطة يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "يتيح التسجيل الموحد لمجموعة الشركات المرتبطة معاملتها ككيان ضريبي واحد، فتُستبعد المعاملات فيما بينها من نطاق ضريبة القيمة المضافة وتُبسَّط الإقرارات."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: التحقق من توفر شروط الارتباط الاقتصادي والمالي والتنظيمي بين الأعضاء، تقديم طلب التسجيل الموحد وتحديد الممثل عن المجموعة، واستبعاد المعاملات الداخلية بين أعضاء المجموعة من نطاق الضريبة.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في التسجيل الضريبي الموحد (VAT Grouping) للمجموعات المرتبطة."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'التسجيل الضريبي الموحد (VAT Grouping) للمجموعات المرتبطة | دليل عملي للمحاسبين',
  'دليل تطبيقي حول التسجيل الضريبي الموحد (VAT Grouping) للمجموعات المرتبطة يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['التسجيل الضريبي الموحد (VAT Grouping) للمجموعات المرتبطة', 'التحقق من توفر شروط الارتباط الاقتصادي والمالي والتنظيمي بين الأعضاء', 'تقديم طلب التسجيل الموحد وتحديد الممثل عن المجموعة', 'استبعاد المعاملات الداخلية بين أعضاء المجموعة من نطاق الضريبة'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق التسجيل الضريبي الموحد (VAT Grouping) للمجموعات المرتبطة؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
