  5,
  $faq$[{"q": "ما أول خطوة لتطبيق تحليل النسب المالية لتقييم الجدارة الائتمانية؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
