(
  'dupont-analysis-profitability-guide',
  (SELECT id FROM public.kb_categories WHERE slug = 'financial-statements'),
  'دليل تحليل ديوبونت DuPont لتفكيك العائد على حقوق الملكية وتشخيص مصادر الربحية',
  'DuPont Analysis: Decomposing Return on Equity to Diagnose Profitability',
  'دليل تطبيقي حول تحليل ديوبونت (DuPont) لتفكيك العائد على حقوق الملكية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to DuPont analysis for decomposing return on equity, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع تحليل ديوبونت (DuPont) لتفكيك العائد على حقوق الملكية يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "يكشف تحليل ديوبونت ما إذا كان تحسّن العائد على حقوق الملكية ناتجًا عن كفاءة تشغيلية حقيقية أو مجرد زيادة في الرافعة المالية التي ترفع المخاطر معها."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: تفكيك العائد على حقوق الملكية إلى هامش الربح ودوران الأصول والرافعة المالية، تحديد أي العناصر الثلاثة يقود التغير في العائد بين فترتين، واستخدام النموذج الموسع لخمسة عوامل لمزيد من الدقة عند الحاجة.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في تحليل ديوبونت (DuPont) لتفكيك العائد على حقوق الملكية."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'تحليل ديوبونت (DuPont) لتفكيك العائد على حقوق الملكية | دليل عملي للمحاسبين',
  'دليل تطبيقي حول تحليل ديوبونت (DuPont) لتفكيك العائد على حقوق الملكية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['تحليل ديوبونت (DuPont) لتفكيك العائد على حقوق الملكية', 'تفكيك العائد على حقوق الملكية إلى هامش الربح ودوران الأصول والرافعة المالية', 'تحديد أي العناصر الثلاثة يقود التغير في العائد بين فترتين', 'استخدام النموذج الموسع لخمسة عوامل لمزيد من الدقة عند الحاجة'],
