(
  'coso-internal-control-framework-guide',
  (SELECT id FROM public.kb_categories WHERE slug = 'audit'),
  'دليل تقييم نظام الرقابة الداخلية وفق إطار COSO للمكونات الخمسة',
  'Evaluating Internal Controls Using the COSO Framework',
  'دليل تطبيقي حول تقييم الرقابة الداخلية وفق إطار COSO يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to evaluating internal controls using the COSO framework, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع تقييم الرقابة الداخلية وفق إطار COSO يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "يقوم الإطار على خمسة مكونات مترابطة: بيئة الرقابة، وتقييم المخاطر، وأنشطة الرقابة، والمعلومات والاتصال، وأنشطة المراقبة، ولا يكتمل التقييم دون فحصها مجتمعة."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: تقييم بيئة الرقابة وتحديد المسؤوليات والقيم الأخلاقية المعتمدة، تقييم أنشطة الرقابة ونظم المعلومات والاتصال ومراقبة الأداء، وتوثيق الفجوات الرقابية ووضع خطة معالجة بأولويات واضحة.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في تقييم الرقابة الداخلية وفق إطار COSO."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'تقييم الرقابة الداخلية وفق إطار COSO | دليل عملي للمحاسبين',
  'دليل تطبيقي حول تقييم الرقابة الداخلية وفق إطار COSO يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['تقييم الرقابة الداخلية وفق إطار COSO', 'تقييم بيئة الرقابة وتحديد المسؤوليات والقيم الأخلاقية المعتمدة', 'تقييم أنشطة الرقابة ونظم المعلومات والاتصال ومراقبة الأداء', 'توثيق الفجوات الرقابية ووضع خطة معالجة بأولويات واضحة'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق تقييم الرقابة الداخلية وفق إطار COSO؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://www.coso.org/"}]$refs$::jsonb,
  $sources$[{"name": "المصدر المرجعي", "url": "https://www.coso.org/"}]$sources$::jsonb,
  'أحمد المدني',
  false,
  'published',
  'editorial',
  '2026-09-07 10:30:00+03'::timestamptz
),
(
  'year-end-external-audit-closing-checklist',
  (SELECT id FROM public.kb_categories WHERE slug = 'audit'),
  'دليل التجهيز للمراجعة الخارجية وقائمة فحص إقفال نهاية السنة المالية',
  'Preparing for External Audit: A Year-End Closing Checklist',
  'دليل تطبيقي حول التجهيز للمراجعة الخارجية وإقفال نهاية السنة المالية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to preparing for external audit and year-end closing, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع التجهيز للمراجعة الخارجية وإقفال نهاية السنة المالية يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "تبدأ مراجعة سلسة من إقفال داخلي منظم؛ فكل يوم يُصرف في تصحيح تسويات أساسية أثناء المراجعة الخارجية هو وقت يُستقطع من فحص الأمور الجوهرية فعليًا."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: مطابقة الحسابات الرئيسية (البنوك، الذمم، المخزون، الأصول الثابتة) قبل بدء المراجعة، تجهيز ملف مصادقات الأرصدة ومذكرات التسويات الجوهرية، وإعداد ملف الإفصاحات والأحداث اللاحقة لتاريخ الميزانية.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في التجهيز للمراجعة الخارجية وإقفال نهاية السنة المالية."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'التجهيز للمراجعة الخارجية وإقفال نهاية السنة المالية | دليل عملي للمحاسبين',
  'دليل تطبيقي حول التجهيز للمراجعة الخارجية وإقفال نهاية السنة المالية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['التجهيز للمراجعة الخارجية وإقفال نهاية السنة المالية', 'مطابقة الحسابات الرئيسية (البنوك، الذمم، المخزون، الأصول الثابتة) قبل بدء المراجعة', 'تجهيز ملف مصادقات الأرصدة ومذكرات التسويات الجوهرية', 'إعداد ملف الإفصاحات والأحداث اللاحقة لتاريخ الميزانية'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق التجهيز للمراجعة الخارجية وإقفال نهاية السنة المالية؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://www.ifac.org/"}]$refs$::jsonb,
  $sources$[{"name": "المصدر المرجعي", "url": "https://www.ifac.org/"}]$sources$::jsonb,
  'أحمد المدني',
  false,
  'published',
  'editorial',
  '2026-09-07 10:40:00+03'::timestamptz
