(
  'choosing-erp-system-smes-saudi-arabia',
  (SELECT id FROM public.kb_categories WHERE slug = 'erp'),
  'دليل اختيار نظام ERP مناسب للمنشآت الصغيرة والمتوسطة في السعودية',
  'Choosing the Right ERP System for SMEs in Saudi Arabia',
  'دليل تطبيقي حول اختيار نظام ERP مناسب للمنشآت الصغيرة والمتوسطة في السعودية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to choosing the right ERP system for SMEs in Saudi Arabia, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع اختيار نظام ERP مناسب للمنشآت الصغيرة والمتوسطة في السعودية يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "لا يقتصر اختيار النظام على قائمة المزايا المعلنة؛ فالتوافق مع منصة فاتورة والقدرة على النمو مع المنشأة أهم من واجهة الاستخدام وحدها."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: التأكد من توافق النظام مع متطلبات الفوترة الإلكترونية (فاتورة) ومراحلها، تقييم قابلية النظام للتوسع مع نمو حجم العمليات وعدد الفروع، ومقارنة تكلفة الترخيص والتنفيذ والدعم الفني على مدى ثلاث سنوات لا سنة واحدة.", "وثّق كل خطوة بمستند مرجعي وموافقة واضحة، وراجع النتيجة مع مسؤول مستقل قبل اعتمادها النهائي في اختيار نظام ERP مناسب للمنشآت الصغيرة والمتوسطة في السعودية."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'اختيار نظام ERP مناسب للمنشآت الصغيرة والمتوسطة في السعودية | دليل عملي للمحاسبين',
  'دليل تطبيقي حول اختيار نظام ERP مناسب للمنشآت الصغيرة والمتوسطة في السعودية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['اختيار نظام ERP مناسب للمنشآت الصغيرة والمتوسطة في السعودية', 'التأكد من توافق النظام مع متطلبات الفوترة الإلكترونية (فاتورة) ومراحلها', 'تقييم قابلية النظام للتوسع مع نمو حجم العمليات وعدد الفروع', 'مقارنة تكلفة الترخيص والتنفيذ والدعم الفني على مدى ثلاث سنوات لا سنة واحدة'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق اختيار نظام ERP مناسب للمنشآت الصغيرة والمتوسطة في السعودية؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://zatca.gov.sa/ar/E-Invoicing/Pages/default.aspx"}]$refs$::jsonb,
  $sources$[{"name": "المصدر المرجعي", "url": "https://zatca.gov.sa/ar/E-Invoicing/Pages/default.aspx"}]$sources$::jsonb,
